 37	          ? action.profile
 38	          : state.confirmedProfile,
 39	        confirmedRequestId: isNewConfirmation
 40	          ? action.requestId
 41	          : state.confirmedRequestId,
 42	        pending: isCurrentRequest ? undefined : state.pending,
 43	        failed: isCurrentRequest ? undefined : state.failed,
 44	      }
 45	    }
 46	    case 'failed':
 47	      if (state.pending?.requestId !== action.requestId) return state
 48	
 49	      return {
 50	        ...state,
 51	        pending: undefined,
 52	        failed: {
 53	          requestId: action.requestId,
 54	          displayName: action.displayName,
 55	        },
 56	      }
 57	  }
 58	}
