 60	export function ProfileForm({ profile }: { profile: Profile }) {
 61	  const [displayName, setDisplayName] = useState(profile.displayName)
 62	  const [saveState, dispatch] = useReducer(saveReducer, {
 63	    confirmedProfile: profile,
 64	    confirmedRequestId: 0,
 65	  })
 66	  const nextRequestId = useRef(0)
 67	
 68	  const visibleName =
 69	    saveState.pending?.displayName ?? saveState.confirmedProfile.displayName
 70	  const failedSubmission = saveState.failed
 71	
 72	  async function saveProfile(submittedName: string) {
 73	    const requestId = ++nextRequestId.current
 74	    dispatch({ type: 'submitted', requestId, displayName: submittedName })
 75	
 76	    try {
 77	      const updatedProfile = await updateProfile(submittedName)
 78	      dispatch({ type: 'succeeded', requestId, profile: updatedProfile })
 79	    } catch {
 80	      dispatch({ type: 'failed', requestId, displayName: submittedName })
 81	    }
 82	  }
 83	
 84	  async function handleSubmit(event: FormEvent) {
 85	    event.preventDefault()
 86	    await saveProfile(displayName)
 87	  }
 88	
 89	  return (
 90	    <form onSubmit={handleSubmit}>
 91	      <p aria-label="Current profile name">{visibleName}</p>
 92	      <label>
 93	        Display name
 94	        <input
 95	          value={displayName}
 96	          onChange={(event) => setDisplayName(event.target.value)}
 97	        />
 98	      </label>
 99	      <button>Save</button>
100	      {failedSubmission && (
101	        <p role="alert">
102	          Save failed. Please retry.{' '}
103	          <button
104	            type="button"
105	            onClick={() => void saveProfile(failedSubmission.displayName)}
106	          >
107	            Retry
108	          </button>
109	        </p>
110	      )}
111	    </form>
112	  )
113	}
